<template><div class="page"><section class="hero"><div><h2>财务规划与净资产</h2><p>基于官方导出账单做预算、识别与趋势分析，不连接个人金融账户</p></div><el-date-picker v-model="period" type="month" value-format="YYYY-MM" :clearable="false" @change="load"/></section><el-tabs v-model="tab"><el-tab-pane label="预算执行" name="budget"><div class="toolbar"><el-button type="primary" @click="budgetVisible=true">设置预算</el-button></div><div class="cards"><article v-for="x in budgets" :key="x.id"><div><b>{{x.category_name||'总预算'}}</b><el-tag :type="x.overBudget?'danger':Number(x.usagePercent)>=Number(x.alert_percent)?'warning':'success'">{{x.overBudget?'已超支':`${x.usagePercent}%`}}</el-tag></div><el-progress :percentage="Math.min(100,Number(x.usagePercent))" :status="x.overBudget?'exception':undefined"/><p>已用 ¥{{x.spent}} / ¥{{x.amount}}</p></article></div></el-tab-pane><el-tab-pane label="订阅与异常" name="alerts"><div class="toolbar"><el-button @click="detect">识别固定支出/订阅</el-button><el-button @click="scan">扫描大额与重复扣款</el-button></div><h3>固定支出与订阅</h3><el-table :data="recurring"><el-table-column prop="merchant" label="商户"/><el-table-column prop="charge_type" label="类型"/><el-table-column prop="expected_amount" label="预计金额"/><el-table-column prop="next_charge_date" label="下次日期"/></el-table><h3>消费异常</h3><div class="anomalies"><el-alert v-for="x in anomalies" :key="x.id" :title="x.message" :type="x.severity==='HIGH'?'error':'warning'" show-icon :closable="false"/></div></el-tab-pane><el-tab-pane label="净资产趋势" name="net"><div class="toolbar"><el-button type="primary" @click="netVisible=true">记录快照</el-button></div><div class="net-summary"><article><small>最新资产</small><b>¥{{latest?.total_assets||0}}</b></article><article><small>最新负债</small><b>¥{{latest?.total_liabilities||0}}</b></article><article><small>最新净资产</small><b>¥{{latest?.net_worth||0}}</b></article></div><div class="trend"><div v-for="x in snapshots" :key="x.snapshot_date" class="trend-row"><time>{{x.snapshot_date}}</time><span :style="{width:`${trendWidth(x.net_worth)}%`}"></span><b>¥{{x.net_worth}}</b></div></div></el-tab-pane><el-tab-pane label="配对与模板" name="tools"><el-card shadow="never"><h3>退款 / 转账 / 信用卡还款配对</h3><div class="inline"><el-input-number v-model="pair.sourceTransactionId" placeholder="源流水 ID"/><el-input-number v-model="pair.targetTransactionId" placeholder="目标流水 ID"/><el-select v-model="pair.relationType"><el-option label="退款" value="REFUND"/><el-option label="转账" value="TRANSFER"/><el-option label="信用卡还款" value="CREDIT_CARD_REPAYMENT"/></el-select><el-button type="primary" @click="reconcile">保存配对</el-button></div></el-card><el-card shadow="never"><h3>导入模板</h3><div class="inline"><el-input v-model="template.name" placeholder="模板名称"/><el-select v-model="template.platform"><el-option label="支付宝" value="ALIPAY"/><el-option label="微信" value="WECHAT"/><el-option label="银行" value="BANK"/></el-select><el-input v-model="template.mappingText" placeholder="交易时间=交易时间,金额=金额"/><el-button @click="saveTemplate">保存</el-button></div><el-tag v-for="x in templates" :key="x.id">{{x.name}} · {{x.platform}}</el-tag></el-card></el-tab-pane></el-tabs>
<el-dialog v-model="budgetVisible" title="设置预算" width="min(520px,94vw)"><el-form label-position="top"><el-form-item label="周期"><el-select v-model="budget.periodType"><el-option label="月度" value="MONTHLY"/><el-option label="年度" value="YEARLY"/></el-select></el-form-item><el-form-item label="周期值"><el-input v-model="budget.periodKey"/></el-form-item><el-form-item label="分类（留空为总预算）"><el-select v-model="budget.categoryId" clearable><el-option v-for="x in categories" :key="x.id" :label="x.categoryName" :value="x.id"/></el-select></el-form-item><el-form-item label="金额"><el-input-number v-model="budget.amount" :min="1" :precision="2"/></el-form-item><el-form-item label="预警比例"><el-slider v-model="budget.alertPercent" :min="10" :max="100" show-input/></el-form-item></el-form><template #footer><el-button @click="budgetVisible=false">取消</el-button><el-button type="primary" @click="saveBudgetForm">保存</el-button></template></el-dialog><el-dialog v-model="netVisible" title="净资产快照" width="min(520px,94vw)"><el-form label-position="top"><el-form-item label="日期"><el-date-picker v-model="net.snapshotDate" type="date" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="总资产"><el-input-number v-model="net.totalAssets" :precision="2"/></el-form-item><el-form-item label="总负债"><el-input-number v-model="net.totalLiabilities" :precision="2"/></el-form-item><el-form-item label="备注"><el-input v-model="net.note"/></el-form-item></el-form><template #footer><el-button type="primary" @click="saveNet">保存</el-button></template></el-dialog></div></template>
<script setup lang="ts">import{ElMessage}from'element-plus';import{computed,onMounted,reactive,ref}from'vue';import{listFinanceCategories,type FinanceCategory}from'@/api/finance';import{detectRecurring,listAnomalies,listBudgets,listImportTemplates,listNetWorth,listRecurring,reconcileTransactions,saveBudget,saveImportTemplate,saveNetWorth,scanAnomalies}from'@/api/financePlanning';const period=ref(new Date().toISOString().slice(0,7)),tab=ref('budget'),budgets=ref<any[]>([]),recurring=ref<any[]>([]),anomalies=ref<any[]>([]),snapshots=ref<any[]>([]),templates=ref<any[]>([]),categories=ref<FinanceCategory[]>([]),budgetVisible=ref(false),netVisible=ref(false);const budget=reactive<any>({periodType:'MONTHLY',periodKey:period.value,categoryId:undefined,amount:3000,alertPercent:80}),net=reactive({snapshotDate:new Date().toISOString().slice(0,10),totalAssets:0,totalLiabilities:0,note:'',details:{}}),pair=reactive<any>({sourceTransactionId:undefined,targetTransactionId:undefined,relationType:'REFUND'}),template=reactive({name:'',platform:'ALIPAY',mappingText:''});const latest=computed(()=>snapshots.value.at(-1));async function load(){[budgets.value,recurring.value,anomalies.value,snapshots.value,templates.value,categories.value]=await Promise.all([listBudgets(period.value).then(x=>x.data),listRecurring().then(x=>x.data),listAnomalies().then(x=>x.data),listNetWorth().then(x=>x.data),listImportTemplates().then(x=>x.data),listFinanceCategories().then(x=>x.data)]);budget.periodKey=period.value;}async function saveBudgetForm(){await saveBudget(budget);budgetVisible.value=false;await load();}async function saveNet(){await saveNetWorth(net);netVisible.value=false;await load();}async function detect(){ElMessage.success(`识别 ${ (await detectRecurring()).data } 个候选`);await load();}async function scan(){ElMessage.success(`发现 ${ (await scanAnomalies()).data } 条异常`);await load();}async function reconcile(){await reconcileTransactions(pair);ElMessage.success('流水配对已保存');}async function saveTemplate(){const mapping=Object.fromEntries(template.mappingText.split(',').map(x=>x.split('=').map(v=>v.trim())).filter(x=>x.length===2));await saveImportTemplate({name:template.name,platform:template.platform,mapping});await load();}function trendWidth(v:number){const max=Math.max(...snapshots.value.map(x=>Math.abs(Number(x.net_worth))),1);return Math.max(3,Math.abs(Number(v))*100/max);}onMounted(load);</script>
<style scoped>.page{display:flex;flex-direction:column;gap:14px}.hero,.toolbar,.inline,.cards article>div{display:flex;align-items:center;justify-content:space-between;gap:10px}.hero h2{margin:0}.hero p{margin:5px 0;color:#718096}.toolbar{justify-content:flex-end;margin-bottom:12px}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.cards article{padding:16px;border:1px solid #e4eaf2;border-radius:14px}.cards p{color:#718096}.anomalies{display:flex;flex-direction:column;gap:8px}.net-summary{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.net-summary article{padding:18px;background:#f6f8ff;border-radius:14px}.net-summary small,.net-summary b{display:block}.net-summary b{margin-top:8px;font-size:22px}.trend{margin-top:18px}.trend-row{display:grid;grid-template-columns:110px 1fr 140px;align-items:center;gap:10px;margin:8px 0}.trend-row span{height:16px;background:#5b7cfa;border-radius:8px}.inline{justify-content:flex-start;flex-wrap:wrap}.el-card+.el-card{margin-top:12px}@media(max-width:768px){.hero,.inline{align-items:stretch;flex-direction:column}.cards,.net-summary{grid-template-columns:1fr}.trend-row{grid-template-columns:90px 1fr}.trend-row b{grid-column:2}}</style>
